/* prog26_wildcard_match.c
 *
 * The original binary implements a simple wildcard matcher.
 * It expects exactly two command‑line arguments:
 *   argv[1] – pattern (may contain '*' and '?')
 *   argv[2] – text to be matched
 *
 * Both strings must be shorter than 65 characters.
 * If the usage is incorrect (wrong number of arguments or a string
 * that is too long) the program prints:
 *
 *     USAGE
 *
 * Otherwise it prints either
 *
 *     MATCH
 *
 * or
 *
 *     NO_MATCH
 *
 * followed by a newline (the original used puts()).
 *
 * The matching algorithm is a classic DP solution that treats '*'
 * as “any sequence (including empty)” and '?' as “any single
 * character”.
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 64          /* 0x41 is the limit used in the binary (strictly < 65) */

static bool wildcard_match(const char *pat, const char *txt)
{
    size_t m = strlen(pat);
    size_t n = strlen(txt);

    /* dp[i][j] – does pat[0..i-1] match txt[0..j-1] ? */
    bool dp[MAXLEN + 1][MAXLEN + 1] = { false };

    dp[0][0] = true;                     /* empty pattern matches empty text */

    /* pattern prefix against empty text */
    for (size_t i = 1; i <= m; ++i) {
        if (pat[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = false;
    }

    for (size_t i = 1; i <= m; ++i) {
        for (size_t j = 1; j <= n; ++j) {
            char pc = pat[i - 1];
            char tc = txt[j - 1];

            if (pc == '*')
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            else if (pc == '?' || pc == tc)
                dp[i][j] = dp[i - 1][j - 1];
            else
                dp[i][j] = false;
        }
    }

    return dp[m][n];
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    if (strlen(pattern) > MAXLEN || strlen(text) > MAXLEN) {
        puts("USAGE");
        return 0;
    }

    if (wildcard_match(pattern, text))
        puts("MATCH");
    else
        puts("NO_MATCH");

    return 0;
}
